/**
 * Storage charged to one tenant: each file's size rounded up to whole
 * megabytes, then summed. Integer division in SQLite rounds down, so the
 * `+ MB - 1` term makes it round up per file, matching what an upload costs.
 */
export async function sumStorageMb(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({
      value: sql<number | null>`sum((${attachments.sizeBytes} + ${BYTES_PER_MB - 1}) / ${BYTES_PER_MB})`,
    })
    .from(attachments)
    .where(orgPredicate(attachments.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

